
#import "JHDragView.h"

#define asconfig @""

@implementation JHDragView {
    UIImageView *iconView;
    UILabel *textLabel;
}

- (instancetype)initWithFrame:(CGRect)frame {
    if (CGRectGetWidth(frame) <= 0 || CGRectGetHeight(frame) <= 0) {
        frame = CGRectMake([UIScreen mainScreen].bounds.size.width - 85 - 15, 
                         [UIScreen mainScreen].bounds.size.height * 0.3, 
                         85, 40);
    }
    self = [super initWithFrame:frame];
    if (self) {
        [self setupUI];
    }
    return self;
}

- (void)setupUI {
    // Main container - black rounded pill-shaped background
    self.layer.cornerRadius = self.frame.size.height / 2;
    self.clipsToBounds = YES;
    self.backgroundColor = [UIColor colorWithRed:0.05 green:0.05 blue:0.05 alpha:0.75];
    self.layer.borderWidth = 1.0;
    self.layer.borderColor = [UIColor colorWithWhite:0.25 alpha:0.3].CGColor;
    
    // Shadow effect
    self.layer.shadowColor = [UIColor blackColor].CGColor;
    self.layer.shadowOffset = CGSizeMake(0, 3);
    self.layer.shadowOpacity = 0.35;
    self.layer.shadowRadius = 6;
    
    // Icon view (left side) - circular
    iconView = [[UIImageView alloc] initWithFrame:CGRectMake(5, 5, 30, 30)];
    iconView.contentMode = UIViewContentModeScaleAspectFill;
    iconView.clipsToBounds = YES;
    iconView.layer.cornerRadius = 15;
    iconView.layer.borderWidth = 1;
    iconView.layer.borderColor = [UIColor colorWithWhite:0.3 alpha:0.4].CGColor;
    
    // Load image from base64
    NSData *imageData = [[NSData alloc] initWithBase64EncodedString:asconfig options:0];
    if (imageData) {
        UIImage *originalImage = [UIImage imageWithData:imageData];
        if (originalImage) {
            // Create circular masked image
            UIGraphicsBeginImageContextWithOptions(iconView.bounds.size, NO, 0.0);
            [[UIBezierPath bezierPathWithOvalInRect:iconView.bounds] addClip];
            [originalImage drawInRect:iconView.bounds];
            iconView.image = UIGraphicsGetImageFromCurrentImageContext();
            UIGraphicsEndImageContext();
        }
    }
    [self addSubview:iconView];
    
    UILabel *textLabel = [[UILabel alloc] initWithFrame:CGRectMake(38, 0, 42, self.frame.size.height)];
    textLabel.text = @"CoreX";
    textLabel.textColor = [UIColor systemBlueColor];          // ← غيرناه للون أزرق
    textLabel.font = [UIFont boldSystemFontOfSize:13];
    textLabel.textAlignment = NSTextAlignmentCenter;
    textLabel.adjustsFontSizeToFitWidth = YES;
    [self addSubview:textLabel];
}

#pragma mark - Touch Handling

- (void)touchesBegan:(NSSet<UITouch *> *)touches withEvent:(UIEvent *)event {
    [UIView animateWithDuration:0.1 animations:^{
        self.transform = CGAffineTransformMakeScale(0.93, 0.93);
    }];
}

- (void)touchesMoved:(NSSet<UITouch *> *)touches withEvent:(UIEvent *)event {
    UITouch *touch = [touches anyObject];
    CGPoint point = [touch locationInView:self.superview];
    self.center = point;
}

- (void)touchesEnded:(NSSet<UITouch *> *)touches withEvent:(UIEvent *)event {
    [UIView animateWithDuration:0.2 animations:^{
        self.transform = CGAffineTransformIdentity;
        [self snapToEdge];
    }];
}

- (void)snapToEdge {
    CGFloat screenWidth = [UIScreen mainScreen].bounds.size.width;
    CGFloat screenHeight = [UIScreen mainScreen].bounds.size.height;
    CGFloat padding = 15;
    
    CGPoint newCenter = self.center;
    
    // Snap to nearest vertical edge
    if (self.center.x < screenWidth / 2) {
        newCenter.x = self.frame.size.width / 2 + padding;
    } else {
        newCenter.x = screenWidth - self.frame.size.width / 2 - padding;
    }
    
    // Keep within vertical bounds
    if (newCenter.y < self.frame.size.height / 2 + padding) {
        newCenter.y = self.frame.size.height / 2 + padding;
    } else if (newCenter.y > screenHeight - self.frame.size.height / 2 - padding) {
        newCenter.y = screenHeight - self.frame.size.height / 2 - padding;
    }
    
    [UIView animateWithDuration:0.3 animations:^{
        self.center = newCenter;
    }];
}

#pragma mark - Public Methods

- (void)setText:(NSString *)text {
    textLabel.text = text;
}

@end